 "api": {
  "abbr": "API",
  "defEn": "a defined set of rules and endpoints that lets one program request services or data from another without knowing its internal implementation",
  "definition": "应用程序编程接口",
  "en": "API",
  "expansion": "Application Programming Interface",
  "href": "content/ch06-automation/6.5-toolchain-architecture.html",
  "wm": {
   "daily": {
    "en": "a point or surface where two things meet and interact",
    "example": "The interface between the kitchen and the dining room is a small serving window.",
    "exampleZh": "厨房和餐厅之间的交接处是一个小小的传菜窗口。",
    "zh": "两个事物相遇并发生交互的接触点或接触面"
   },
   "derivation": [
    {
     "stepLabel": "本义",
     "text": "interface = inter（之间）+ face（面），字面就是「夹在中间的那一面」——两个空间或系统交接的地方。"
    },
    {
     "stepLabel": "日常引申",
     "text": "人机交互也叫 interface（用户界面）；人际关系、部门协作也常用 interface：the interface between sales and engineering（销售与研发之间的衔接环节）。"
    },
    {
     "stepLabel": "跨到计算机",
     "text": "一个 App 要让另一个服务帮忙（付款、发消息、查天气），不能伸进对方服务器里乱翻。双方约定好「从哪个门进出、带什么格式的请求」——这个门就是 API。英语用 interface，因为它强调「边界上的接触面」，而不是「里面怎么实现的」。"
    }
   ],
   "derivationSummary": "两面之间的接触面 → 人机接触面（界面）→ 程序与程序之间的接触面（API）",
   "etymology": "application ← 拉丁语 applicāre（贴上、施用）；programming ← 希腊语 programma（公开书面通知）→ program；interface ← inter（之间）+ face（面）",
   "literal": "字面：供「应用程序」通过「编程」来使用的「接触面」",
   "oneLiner": "程序之间打交道的「接触面」——你按约定发请求，它按约定回结果。",
   "parts": [
    {
     "role": "使用方——要完成任务的具体程序或应用",
     "senseHint": "应用程序",
     "word": "application"
    },
    {
     "role": "方式——通过写代码来调用，不是人手点界面",
     "senseHint": "编程",
     "word": "programming"
    },
    {
     "role": "核心意象——两者之间的接触面，信息从这里进出",
     "senseHint": "接口、接触面",
     "word": "interface"
    }
   ],
   "pitfalls": [
    {
     "right": "日常更常指「交接处、接触面」：user interface（用户界面）、interface with clients（与客户打交道）。听到 interface 先想「两面相接的地方」，再想 REST API。",
     "wrong": "以为 interface 在生活里只等于「接口」"
    },
    {
     "right": "日常英语里 application 最高频的义项其实是「申请（书）」：submit a job application（递交求职申请）、Applications close on Friday（申请周五截止）、a planning application（规划许可申请）。只有在 API / mobile application 这类语境里，它才是「应用程序」。",
     "wrong": "因为天天见 App，把 application 一律读成「应用程序」"
    }
   ],
   "tech": {
    "en": "a defined set of rules and endpoints that lets one program request services or data from another without knowing its internal implementation",
    "example": "Call the payment API to charge the customer's card.",
    "exampleZh": "调用支付 API 向客户的银行卡扣款。",
    "zh": "一套明确定义的规则与端点，让一个程序能在不了解对方内部实现的情况下请求服务或获取数据"
   }
  },
  "zh": "应用程序编程接口"
 },
