 "chaos engineering": {
  "defEn": "a discipline of experimenting on production or production-like systems by injecting controlled failures—such as killing instances or adding latency—to build confidence in resilience before real outages strike",
  "definition": "在受控条件下主动注入故障、验证系统韧性假设的实践 —— 术语表只收录工具侧的 Simian Army/Chaos Monkey。",
  "en": "Chaos Engineering",
  "href": "content/ch02-core-principles/2.6-chaos-engineering.html",
  "ipa": "/ˈkeɪɑːs ˌendʒɪˈnɪrɪŋ/",
  "parts": [
   "chaos",
   "engineering"
  ],
  "wm": {
   "derivation": [
    {
     "stepLabel": "本义",
     "text": "chaos 在希腊语里是「裂开的虚空」，英语里就是 complete chaos（一片狼藉）：The kids left the house in chaos。engineering 是「用科学方法设计、建造、验证」——bridge engineering（桥梁工程）。"
    },
    {
     "stepLabel": "为何凑在一起",
     "text": "传统测试在实验室里很干净；线上却是 messy 的——实例会死、网络会抖、依赖会超时。Netflix 把「主动制造这类混乱」做成一套可重复的实验纪律，并命名为 Chaos Engineering，是专有方法论名。"
    },
    {
     "stepLabel": "跨到计算机",
     "text": "不是等半夜 pager 响，而是白天按计划注入故障：随机杀 Pod、断网、拖慢数据库。观察系统是否降级优雅、告警是否准确、用户是否无感——在真灾难到来前把弱点挖出来。"
    },
    {
     "stepLabel": "为什么用 engineering 而不是 testing",
     "text": "testing 暗示「对照规格检查」。engineering 强调「在复杂系统里设计实验、设假设、控爆炸半径、从结果改架构」。英文故意用 engineering，是要你把这事当成持续改进韧性，不是多写几个用例。"
    }
   ],
   "derivationSummary": "chaos「混乱」+ engineering「系统化设计与实验」→ 主动找乱子，证明系统扛得住",
   "etymology": "chaos ← 希腊语 khaos（裂隙、虚空、原始混乱）；engineering ← engineer + -ing；engineer ← 古法语 engigneor（攻城器械的建造者）← 拉丁语 ingenium（天生的才智、巧思）← in- + gignere（生出）——同源词还有 engine、ingenious",
   "literal": "字面：用工程手段「制造并研究混乱」",
   "oneLiner": "故意在系统里制造可控混乱，看它在真出事前会不会先露馅。",
   "parts": [
    {
     "role": "实验材料——有意引入的混乱、故障、不可预测",
     "senseHint": "混乱、无序",
     "word": "chaos"
    },
    {
     "role": "做法——不是碰运气，而是有假设、有对照、有度量的实验",
     "senseHint": "工程、设计",
     "word": "engineering"
    }
   ],
   "pitfalls": [
    {
     "right": "日常 chaos 就是「乱套了」：My schedule is chaos this week（我这周日程一团糟）。chaos engineering 借的是「故意弄乱」的画面，不是数学里的混沌系统。",
     "wrong": "以为 chaos 在生活里也是「混沌理论」"
    },
    {
     "right": "它有假设、爆炸半径、回滚开关：We're not breaking things randomly—we're running a controlled chaos experiment。和 vandalism（蓄意破坏）不是一回事。",
     "wrong": "把 chaos engineering 当成「线上随便搞破坏」"
    },
    {
     "right": "engineering 常指「工程化地做某事」：social engineering（社会工程学，指骗人手段）。chaos engineering 是「把制造故障这件事工程化」，不是「混乱的工程师」。",
     "wrong": "以为 engineering 在这里指「工程师这个职业」"
    }
   ],
   "tech": {
    "en": "a discipline of experimenting on production or production-like systems by injecting controlled failures—such as killing instances or adding latency—to build confidence in resilience before real outages strike",
    "example": "Chaos engineering revealed that our cache layer had no graceful fallback when a node died.",
    "exampleZh": "混沌工程暴露出缓存层在某个节点挂掉时没有优雅降级。",
    "zh": "在生产或类生产环境中注入可控故障（如杀掉实例、增加延迟）做实验，在真实事故到来之前验证系统韧性的工程方法"
   }
  },
  "zh": "混沌工程"
 },
