 "continuous delivery": {
  "abbr": "CD",
  "badges": [
   "core",
   "hot"
  ],
  "defEn": "a software engineering practice where every change that passes automated tests can be released to production at any time, typically via a one-click or fully automated deploy",
  "definition": "每个通过流水线的版本都随时具备可发布状态，发不发布由人决定。",
  "en": "Continuous delivery",
  "href": "content/ch03-key-practices/3.3-delivery-vs-deployment.html",
  "ipa": "/kənˈtɪnjuəs dɪˈlɪvəri/",
  "kp": "kp-3-3-1",
  "parts": [
   "continuous",
   "delivery"
  ],
  "wm": {
   "daily": {
    "en": "the act of bringing or handing something to its intended recipient",
    "example": "We offer free delivery on orders over $50.",
    "exampleZh": "订单满五十美元免配送费。",
    "zh": "把东西送到、交到收件人手里"
   },
   "derivation": [
    {
     "stepLabel": "本义",
     "text": "deliver 本义是「送交到某人手中、使脱离束缚」。delivery 可指快递送达、演讲交付，也可指 childbirth（分娩——把孩子「送出来」）。"
    },
    {
     "stepLabel": "日常引申",
     "text": "商业英语里 delivery 就是「配送/交付」：next-day delivery（次日达）、on-time delivery（准时交货）。重点是「把成品交到对方可用的地方」，不是「制造过程」。"
    },
    {
     "stepLabel": "跨到计算机",
     "text": "CD 在 CI 之上再加一层：不仅代码合得拢、测得过，还要「随时能交到 production 用户手里」。为什么用 delivery 不用 release？因为 delivery 强调「交到用户可用」这一环——发布按钮按下去，价值就送达。continuous 同样指「不断档」，不是「发布很频繁」这一个意思，而是「任何时刻都具备交付能力」。"
    }
   ],
   "derivationSummary": "「递送到手」→ 快递/分娩/交付成果 → 软件工程里「随时能把可用版本交到线上用户」",
   "etymology": "delivery ← 古法语 delivrer（to set free, hand over）← 拉丁语 dē + liberāre（to liberate）；continuous 见 continuous-integration",
   "literal": "字面：不间断地把（软件）交到使用者手中",
   "oneLiner": "让软件改动随时处于「能安全发布」的状态，需要时可一键上线。",
   "parts": [
    {
     "role": "修饰节奏——发布能力「不断档」，不是攒批",
     "senseHint": "连续不断的",
     "word": "continuous"
    },
    {
     "role": "核心动作——把可用的软件交到用户/production",
     "senseHint": "递送、交付",
     "word": "delivery"
    }
   ],
   "pitfalls": [
    {
     "right": "最常见的是「配送」：The delivery driver called. 快递司机来电话了。food delivery 就是外卖配送，不是「食物项目交付」。",
     "wrong": "把 delivery 在生活里也只读成「交付（项目）」"
    },
    {
     "right": "continuous delivery 是「随时可发布」；continuous deployment 才是「改完就自动上线」。Many teams do CD but still deploy manually on Fridays. 很多团队有持续交付能力，但仍选择周五手动上线。",
     "wrong": "混淆 CD 与「每次改动都自动上线」"
    }
   ],
   "tech": {
    "en": "a software engineering practice where every change that passes automated tests can be released to production at any time, typically via a one-click or fully automated deploy",
    "example": "With CD in place, we can ship hotfixes within the hour.",
    "exampleZh": "有了持续交付，我们一小时内就能发出热修复。",
    "zh": "一种工程实践：每次通过自动化测试的改动，随时都可以发布到生产环境，通常一键或全自动部署即可上线"
   }
  },
  "zh": "持续交付"
 },
 "continuous deployment": {
  "abbr": "CD",
  "badges": [
   "core",
   "warn"
  ],
  "defEn": "a practice where every change that passes automated tests is automatically released to production without a manual approval gate—stricter than continuous delivery, which may stop at a production-ready artifact",
  "definition": "通过全部自动化测试的版本自动进入生产，没有人工放行环节。",
  "en": "Continuous deployment",
  "href": "content/ch03-key-practices/3.3-delivery-vs-deployment.html",
  "ipa": "/kənˈtɪnjuəs dɪˈplɔɪmənt/",
  "kp": "kp-3-3-2",
  "parts": [
   "continuous",
   "deployment"
  ],
  "wm": {
   "daily": {
    "en": "continuous = without interruption; deployment = putting resources into position for use",
    "example": "The deployment of peacekeepers took three weeks.",
    "exampleZh": "维和部队的部署花了三周。",
    "zh": "continuous 指不间断；deployment 指把资源部署到可使用的位置"
   },
   "derivation": [
    {
     "stepLabel": "本义",
     "text": "deploy 来自法语「展开、摊开」——军事上把部队展开到阵地；deployment 是名词化的「展开行动」。"
    },
    {
     "stepLabel": "日常引申",
     "text": "deployment 在新闻里常指人力或资源的调配：troop deployment、deployment of nurses。核心是「从仓库/基地摆到该干活的地方」。"
    },
    {
     "stepLabel": "跨到计算机",
     "text": "发布软件就是把 build 摆到服务器上让用户访问——这就是 deployment。加上 continuous，主张每次合入都自动走完这条路。"
    },
    {
     "stepLabel": "与 continuous delivery 的分界",
     "text": "delivery 强调「随时能交付」——产物已生产就绪，但可能仍等人工点发布。deployment 再往前一步：连「点发布」也自动化。英语用 deployment 而非 release，是因为重点在「摆到位、展开服务」，不是「办发布会」。"
    }
   ],
   "derivationSummary": "deploy「展开部队」→ deployment「展开到位」→ 软件自动展开到生产 = continuous deployment",
   "etymology": "continuous ← 拉丁语 continuus（连在一起的）；deployment ← 法语 déployer（展开）← 拉丁语 displicāre（摊开）",
   "literal": "字面：不间断地把（软件）部署到位",
   "oneLiner": "代码一通过验证就自动部署到生产，中间几乎不留人工断口。",
   "parts": [
    {
     "role": "修饰频率——强调合并与发布之间没有大断口",
     "senseHint": "连续不断的",
     "word": "continuous"
    },
    {
     "role": "终点动作——把软件真正摆到用户能用的环境里",
     "senseHint": "部署、展开",
     "word": "deployment"
    }
   ],
   "pitfalls": [
    {
     "right": "delivery 只承诺「随时可上线」，按不按发布按钮仍由人决定；deployment 连这一步也自动化。日常英语里这两个词的分工也一样：A food delivery arrived at the door. 是「东西已经送到你手上」；The deployment of extra staff eased the queues. 是「把人手摆到该在的岗位上」。",
     "wrong": "把 continuous deployment 和 continuous delivery 当成一回事（缩写都是 CD）"
    },
    {
     "right": "日常 deployment 是「调配到位」：The deployment of new staff started Monday. 新人手周一开始到岗。软件里指把版本摆进运行环境的全过程。",
     "wrong": "把 deployment 只翻译成「部署工具」"
    },
    {
     "right": "continuous 是「中间不断档」。a continuous line 是一条没断的线；continual interruptions 才是反复打断。",
     "wrong": "以为 continuous = 时间长"
    }
   ],
   "tech": {
    "en": "a practice where every change that passes automated tests is automatically released to production without a manual approval gate—stricter than continuous delivery, which may stop at a production-ready artifact",
    "example": "With continuous deployment, a green main branch goes straight to prod.",
    "exampleZh": "采用持续部署后，主干一旦变绿就直接上生产。",
    "zh": "每次通过自动化测试的改动都会自动发布到生产环境，无需人工放行——比 continuous delivery 更激进，后者可能只做到「随时可上线」而仍保留人工决策"
   }
  },
  "zh": "持续部署"
 },
