 "continuous integration": {
  "abbr": "CI",
  "badges": [
   "core",
   "hot"
  ],
  "defEn": "a practice where developers merge their code into a shared mainline several times a day, each merge verified by an automated build and test run",
  "definition": "开发者频繁把代码合入主干，每次合入都自动构建并测试，尽早暴露集成冲突。",
  "en": "Continuous integration",
  "href": "content/ch03-key-practices/3.2-continuous-integration.html",
  "ipa": "/kənˈtɪnjuəs ˌɪntɪˈɡreɪʃn/",
  "kp": "kp-3-2-1",
  "parts": [
   "continuous",
   "integration"
  ],
  "wm": {
   "daily": {
    "en": "combining separate parts into a working whole, without interruption",
    "example": "The integration of the two teams took six months.",
    "exampleZh": "两个团队的融合花了六个月。",
    "zh": "把分散的部分不间断地合成一个能运作的整体"
   },
   "derivation": [
    {
     "stepLabel": "本义",
     "text": "拉丁语 integer 意为「未被碰过的、完整的」（数学的「整数」integer 就是这个词）。integrāre = 使某物恢复成一个完整体。"
    },
    {
     "stepLabel": "日常引申",
     "text": "英语里 integration 最常见的是「融合、一体化」：racial integration（种族融合）、integrate into the team（融入团队）——都是原本分开的部分变成一个整体。"
    },
    {
     "stepLabel": "跨到计算机",
     "text": "多人各自在分支上改代码时，同一个系统被切成了互不知情的几份——它「不完整」了。把这些分支合回一个能编译能跑的主干，正是「使之重新完整」。所以 integration 在这里描述的是状态修复，不是「把零件装配起来」。"
    },
    {
     "stepLabel": "为什么加 continuous",
     "text": "continuous 不是「持续时间长」，而是「中间没有断口」。攒到发布前一次性合并＝断口很大；每天合几次＝几乎没有断口。CI 的全部主张就在这个词上。"
    }
   ],
   "derivationSummary": "integer「完整的」→ integrate「使复原为一个整体」→ 代码散在各分支就是「碎了」，合回可用主干就是「使之重新完整」",
   "etymology": "continuous ← 拉丁语 continuus（连在一起的）← continēre；integration ← 拉丁语 integer（完整的、未被碰过的）→ integrāre（使复原完整）",
   "literal": "字面：不间断地「使之重新完整」",
   "oneLiner": "让每个人的改动不断合回主干，并自动验证还能不能跑。",
   "parts": [
    {
     "role": "修饰频率——强调「中间不断口」，不是「时间长」",
     "senseHint": "连续不断的",
     "word": "continuous"
    },
    {
     "role": "动作本身——把分开的东西合成一个完整的整体",
     "senseHint": "融合、使成整体",
     "word": "integration"
    }
   ],
   "pitfalls": [
    {
     "right": "日常英语里它压倒性地表示「融合 / 一体化 / 融入」。听到 integration policy 要想到移民融入政策，不是「集成策略」。",
     "wrong": "把 integration 在生活里也读成「集成」"
    },
    {
     "right": "continuous 是不间断的（一条线），continual 是反复但有间隔（一串点）。CI 用的是前者。",
     "wrong": "以为 continuous = continual"
    }
   ],
   "tech": {
    "en": "a practice where developers merge their code into a shared mainline several times a day, each merge verified by an automated build and test run",
    "example": "Our CI pipeline runs the full test suite on every push.",
    "exampleZh": "我们的 CI 流水线在每次推送时跑完整测试套件。",
    "zh": "开发者每天多次把自己的代码合并进共享主干，每次合并都由自动构建和测试来验证"
   }
  },
  "zh": "持续集成"
 },
