 "definition of done": {
  "abbr": "DoD",
  "defEn": "a shared team checklist describing everything that must be true for any backlog item to count as fully complete, beyond just meeting that item's acceptance criteria",
  "definition": "完成的定义。术语表收录的是 Scrum roles, artifacts and events，未单列 DoD",
  "en": "Definition of Done",
  "href": "content/ch04-frameworks/4.2-agile-scrum.html",
  "ipa": "/ˌdɛfɪˈnɪʃən əv dʌn/",
  "parts": [
   "definition",
   "done"
  ],
  "wm": {
   "derivation": [
    {
     "stepLabel": "本义",
     "text": "define 是「下定义、划边界」；done 就是「做完了」：Are you done with dinner?（你吃完没？）"
    },
    {
     "stepLabel": "日常引申",
     "text": "项目口语里常说 That's not done yet——暗示还有收尾工作（签字、清理现场），不只是主体干完。"
    },
    {
     "stepLabel": "跨到计算机",
     "text": "单个用户故事可有 acceptance criteria，但「合并代码」不等于「可上线」。DoD 是团队级底线：测试、文档、监控、合规等横切要求。"
    },
    {
     "stepLabel": "为什么是这个词",
     "text": "Scrum 刻意用 definition of done 而不是 quality gate，因为要回答哲学问题：什么叫 done？——把默契写下来，减少「我觉得做完了」的争议。"
    }
   ],
   "derivationSummary": "先划清「完成」的边界 → 避免每个人对 done 有不同标准",
   "etymology": "definition ← 拉丁语 dēfīnīre（划清界限）；done ← do 的过去分词",
   "literal": "字面：对「done 是什么意思」的界定",
   "oneLiner": "团队共同约定：一张卡要过哪些关卡，才算真的「做完」，而不只是「代码合了」。",
   "parts": [
    {
     "role": "把含糊的「做完」说清楚——团队级共识，不是个人感觉",
     "senseHint": "定义、界定",
     "word": "definition"
    },
    {
     "role": "核心状态词——何时可以喊停、交付",
     "senseHint": "做完的",
     "word": "done"
    }
   ],
   "pitfalls": [
    {
     "right": "日常 done 就是「事情了结」：I'm done arguing（我不想吵了）、done deal（定局了）——都指状态结束，不是某个动作。",
     "wrong": "把 done 理解成「提交代码」"
    },
    {
     "right": "验收标准管「这条需求对不对」；完成定义管「任何进主干的改动都要满足哪些共通门槛」。例：Story AC checks login works; DoD requires tests and review for every story.",
     "wrong": "混淆 DoD 和 acceptance criteria"
    }
   ],
   "tech": {
    "en": "a shared team checklist describing everything that must be true for any backlog item to count as fully complete, beyond just meeting that item's acceptance criteria",
    "example": "Our definition of done includes code review, unit tests, and updated docs before we close the ticket.",
    "exampleZh": "我们的完成定义包括代码评审、单元测试和文档更新，之后才能关单。",
    "zh": "团队共享的一份检查清单，规定任何待办项除满足自身验收标准外，还必须具备哪些条件才算彻底完成"
   }
  },
  "zh": "完成的定义"
 },
