 "downtime": {
  "abbr": "DOWNTIME",
  "defEn": "period when a production system is unavailable or degraded enough that users cannot rely on it, often tracked for SLAs and incident metrics",
  "definition": "精益浪费类型 DOWNTIME，八项。术语表词条为 Lean types of Waste (DOWNTIME)，不要写成「七种浪费 DOWNTIME」 —— 比经典七种浪费多出 Non-utilized talent 一项",
  "en": "DOWNTIME",
  "expansion": "Defects · Overproduction · Waiting · Non-utilized talent · Transportation · Inventory · Motion · Extra-processing",
  "href": "content/ch04-frameworks/4.3-lean.html",
  "ipa": "/ˈdaʊntaɪm/",
  "wm": {
   "daily": {
    "en": "time when a machine, service, or activity is not operating or available for use",
    "example": "The factory had six hours of downtime after the power cut.",
    "exampleZh": "停电后，工厂停了六个小时。",
    "zh": "机器、服务或活动无法运转、不能使用的这段时间"
   },
   "derivation": [
    {
     "stepLabel": "本义",
     "text": "down 可指「倒下、停止工作」；time 是时段。合在一起就是「停下来的那段时间」。"
    },
    {
     "stepLabel": "日常引申",
     "text": "工厂、电梯、生产线都说 downtime。The elevator's downtime lasted all morning——完全是非 IT 场景。"
    },
    {
     "stepLabel": "跨到计算机",
     "text": "网站、API、数据库若用户打不开或用不了，那段不可用窗口就叫 downtime，与 uptime、availability 一起算 SLA。"
    },
    {
     "stepLabel": "为什么用这个词",
     "text": "英语没有单独发明新词，只是把工业里「停机」的说法原样搬到服务器上。它强调的是时间长度，不是故障类型本身。"
    }
   ],
   "derivationSummary": "机器 down 了 → 这段不能用的时光就是 downtime → 线上服务同理",
   "etymology": "复合词 down + time；down 在机械语境里早就有「停机、失灵」之意，与 uptime 成对使用",
   "literal": "字面：处于「down（停掉）」状态的「时间」",
   "morphemes": [
    {
     "from": "古英语 dūn 本义是「山、丘」；副词 down 由短语 of dūne（从山上下来）缩合而成，才有「向下」，再引申出「倒下、停机」",
     "meaning": "停下、不运转、失效",
     "piece": "down"
    },
    {
     "from": "古英语 tīma（时间、时段）",
     "meaning": "一段时间",
     "piece": "time"
    }
   ],
   "oneLiner": "本来该运转的时候，却停下来、用不了的那段时间。",
   "pitfalls": [
    {
     "right": "日常里 downtime 也包括「暂时不能正常使用」。The app had downtime during maintenance 可能是计划内维护，不一定是灾难。",
     "wrong": "以为 downtime 只指「完全宕机、全站黑屏」"
    },
    {
     "right": "outage 常强调「服务中断事件」；downtime 强调「持续了多久」。一次 outage 可能只造成两分钟 downtime。",
     "wrong": "和 outage 完全等同"
    }
   ],
   "tech": {
    "en": "period when a production system is unavailable or degraded enough that users cannot rely on it, often tracked for SLAs and incident metrics",
    "example": "The deploy caused twenty minutes of downtime for EU users.",
    "exampleZh": "这次部署让欧洲用户经历了二十分钟宕机。",
    "zh": "生产系统不可用或严重降级、用户无法正常使用的那段时间，常纳入 SLA 与事故指标统计"
   }
  },
  "zh": "DOWNTIME"
 },
