 "gitops": {
  "defEn": "an operational model where the desired state of infrastructure and applications is declared in Git, and automated controllers reconcile the live environment to match that repository",
  "definition": "以 Git 仓库为唯一事实源驱动部署的做法，常被误当成 IaC 的官方术语。",
  "en": "GitOps",
  "ipa": "/ˈɡɪtɒps/",
  "wm": {
   "derivation": [
    {
     "stepLabel": "本义",
     "text": "operations 在英语里指任何组织「日常运转、维持服务」的工作，不限于计算机。"
    },
    {
     "stepLabel": "日常引申",
     "text": "在软件团队里 operations 常缩写为 Ops，指部署、监控、故障处理等让产品在线运行的职责，与开发（dev）相对。"
    },
    {
     "stepLabel": "跨到计算机",
     "text": "基础设施即代码（IaC）把服务器、网络、K8s 清单都写成可版本化的文件。Git 已是开发者最熟悉的变更与审批工具。"
    },
    {
     "stepLabel": "为什么叫 GitOps",
     "text": "GitOps 主张：Git 仓库是「期望状态」的唯一来源；合并即宣告意图，控制器自动 diff 并应用到集群。名字强调的不是新工具，而是把 Ops 的流程锚定在 Git 工作流上。"
    }
   ],
   "derivationSummary": "operations 本是「让系统日常转起来」→ 云原生里配置也变成代码 → 既然代码本就用 Git 管，干脆让 Git 也成为集群状态的权威记录 → GitOps",
   "etymology": "GitOps 为 2017 年前后由 Weaveworks 推广的合成词：Git（Linus Torvalds 命名的版本控制系统，意为「蠢货」的自嘲昵称）+ operations（运作、运营）",
   "literal": "字面：用 Git 来做的 Operations（运维）",
   "oneLiner": "用 Git 仓库当唯一真相来源，自动把集群状态同步成仓库里描述的样子。",
   "parts": [
    {
     "role": "真相来源与变更记录——版本库既是配置存档，也是审批与审计轨迹",
     "senseHint": "版本控制系统",
     "word": "git"
    },
    {
     "role": "后半段点明这是运维实践，不是单纯写代码",
     "senseHint": "运维、运营",
     "word": "ops"
    }
   ],
   "pitfalls": [
    {
     "right": "Ops 在此是 operations 的缩写，指运维职能。说 dev vs ops 时，想的是「开发 vs 运维」，不是「开发 vs 操作」。",
     "wrong": "把 Ops 理解成「操作（operation 的动词）」"
    },
    {
     "right": "GitOps 还要求自动对账（reconciliation）：仓库改了，集群应被自动拉向新状态；仅把 YAML 放进 Git 而不自动同步，还不算完整 GitOps。",
     "wrong": "以为 GitOps 等于「用 Git 存配置文件」"
    }
   ],
   "tech": {
    "en": "an operational model where the desired state of infrastructure and applications is declared in Git, and automated controllers reconcile the live environment to match that repository",
    "example": "We fixed the outage by reverting the GitOps manifest and letting the controller resync.",
    "exampleZh": "我们通过回滚 GitOps 清单并让控制器重新同步来修复故障。",
    "zh": "一种运维模式：基础设施和应用的目标状态都写在 Git 里，由自动化控制器把线上环境持续对齐到仓库所描述的状态"
   }
  },
  "zh": "GitOps"
 },
