 "iac": {
  "abbr": "IaC",
  "badges": [
   "plain",
   "hot"
  ],
  "defEn": "managing servers, networks, and cloud resources through declarative or imperative code files stored in version control, instead of manual console clicks",
  "definition": "基础设施即代码。Blueprint 的 CALMS-A 描述句逐字点名 infrastructure-as-code",
  "en": "IaC",
  "expansion": "Infrastructure as Code",
  "href": "content/ch06-automation/6.3-iac.html",
  "kp": "kp-6-3-1",
  "wm": {
   "derivation": [
    {
     "stepLabel": "本义",
     "text": "infrastructure = infra（在下）+ structure（结构），字面「下面的结构」——道路、桥梁、电网等支撑上层运作的底子。code 原指「法典、成文规则」（legal code），后来也指「用符号写下的指令」。"
    },
    {
     "stepLabel": "日常引申",
     "text": "infrastructure 在新闻和商务里极常见：transport infrastructure（交通基础设施）、social infrastructure（社会基础服务）。code 在日常可指「行为规范」：code of conduct（行为准则）——成文的、可遵照执行的规则。"
    },
    {
     "stepLabel": "跨到计算机",
     "text": "早期运维在网页控制台点鼠标建服务器，无法审查、无法回滚。IaC 把 infra 写成 .tf / .yaml 文件，像管应用代码一样：进 Git、走 PR、可 diff。as code 这个句式（X as code）表示「用管代码的那套纪律来管 X」——可版本化、可自动化、可重复。英文选 infrastructure 而非 equipment，因为强调的是支撑整个系统运行的「底层结构」，不是某一台机器。"
    }
   ],
   "derivationSummary": "infrastructure 是「底下的结构」→ code 是「可执行的文本规程」→ as 表示「以……的方式」→ 用管代码的办法管基础设施",
   "etymology": "infrastructure ← 拉丁语 infra（在下）+ structūra（结构）；code ← 拉丁语 codex（书、法典）",
   "literal": "字面：把基础设施当作代码来对待",
   "oneLiner": "把服务器、网络这些「地基」也用代码文件来描述和管理。",
   "parts": [
    {
     "role": "被管理的对象——系统跑起来所依赖的底层设施",
     "senseHint": "基础设施",
     "word": "infrastructure"
    },
    {
     "role": "管理手段——用可版本化的文本而非手工操作",
     "senseHint": "代码、规程",
     "word": "code"
    }
   ],
   "pitfalls": [
    {
     "right": "日常 infrastructure 范围很广：critical infrastructure（关键基础设施，含水电交通）。在公司里常说 invest in infrastructure，指底层能力建设，不限于 IT。",
     "wrong": "把 infrastructure 只理解成「云服务器」"
    },
    {
     "right": "as code 强调的是「像对待代码一样：文本化、版本化、可自动化」。Configuration files 和 YAML 也算 code in this sense，不一定是 Python。",
     "wrong": "以为 as code 里的 code 只指编程语言"
    },
    {
     "right": "IaC 定义「基础设施应该长什么样」；deployment 是「把应用摆上去跑」。日常类比：IaC 是建筑图纸，deployment 是搬家入住。",
     "wrong": "把 IaC 和 deployment 混为一谈"
    }
   ],
   "tech": {
    "en": "managing servers, networks, and cloud resources through declarative or imperative code files stored in version control, instead of manual console clicks",
    "example": "We use Terraform modules to keep our infrastructure as code in sync across regions.",
    "exampleZh": "我们用 Terraform 模块让各区域的基础设施即代码保持同步。",
    "zh": "通过存放在版本库中的声明式或命令式代码文件来管理服务器、网络和云资源，而不是靠控制台手工点击"
   }
  },
  "zh": "基础设施即代码"
 },
