 "kanban": {
  "badges": [
   "core",
   "hot"
  ],
  "defEn": "a lean workflow method that visualizes work on a board with columns (e.g., To Do, In Progress, Done), limits work in progress, and pulls new tasks only when capacity frees up",
  "definition": "通过可视化工作流与限制在制品来暴露瓶颈、以拉动方式推进工作的方法。",
  "en": "Kanban",
  "href": "content/ch03-key-practices/3.7-kanban.html",
  "ipa": "/ˈkɑːnbɑːn/",
  "kp": "kp-3-7-1",
  "wm": {
   "derivation": [
    {
     "stepLabel": "本义",
     "text": "日语 kanban 原指工厂里标明「现在该生产什么、产多少」的标牌，信息一眼可见。"
    },
    {
     "stepLabel": "制造引申",
     "text": "丰田体系里，看板控制物料在工序间流动：下游空了才向上游要货，避免堆积。"
    },
    {
     "stepLabel": "跨到计算机",
     "text": "任务列表看不见瓶颈时，团队借 kanban 把每列工作量显式化，并用 WIP limit 防止「同时进行太多」。英文直接借用日语词，因为它命名的是「可视化 + 拉动」这套方法，而不是普通白板。"
    }
   ],
   "derivationSummary": "工厂里的状态标示板 → 可视化在制品与拉动 → 软件团队用列和 WIP 限制管理任务流",
   "etymology": "日语 看板（かんばん，signboard）；由丰田生产体系引入英语",
   "literal": "字面：日语「看板」——让人一眼看见状态与流动的标示板",
   "morphemes": [
    {
     "from": "日语 看（かん）",
     "meaning": "看、标示",
     "piece": "kan"
    },
    {
     "from": "日语 板（ばん）",
     "meaning": "板、牌子",
     "piece": "ban"
    }
   ],
   "oneLiner": "用一块可视化的板子，限制在制品，让工作在拉动式节奏里流动。",
   "pitfalls": [
    {
     "right": "严格意义上 kanban 还包含 WIP 限制和拉动式取活；随便贴便利贴的 board 不一定是 kanban system。",
     "wrong": "以为 kanban 就是「任何任务看板」"
    },
    {
     "right": "英语母语者在非职场语境里几乎不会单独说 kanban；日常说 whiteboard 或 board。只有技术讨论里才说 We use kanban on Jira.",
     "wrong": "把 kanban 当成 daily English 里的普通词去造句"
    }
   ],
   "tech": {
    "en": "a lean workflow method that visualizes work on a board with columns (e.g., To Do, In Progress, Done), limits work in progress, and pulls new tasks only when capacity frees up",
    "example": "We moved from a long backlog list to a kanban board with a WIP limit of three.",
    "exampleZh": "我们从一长串待办列表改成了看板，在制品上限设为三。",
    "zh": "一种精益工作流方法：在看板上用列（如待办、进行中、已完成）可视化工作，限制在制品数量，并只在有空余产能时拉动新任务"
   }
  },
  "zh": "看板方法"
 },
