 "key performance indicator": {
  "abbr": "KPI",
  "defEn": "in engineering and product teams, the primary metrics chosen to judge whether systems, releases, or initiatives are meeting their goals, distinct from the full dashboard of everything measurable",
  "definition": "关键绩效指标。通用管理词汇，DOFD 强调的是价值驱动指标而非泛指的 KPI",
  "en": "Key Performance Indicator",
  "href": "content/ch07-metrics/7.1-why-measure.html",
  "ipa": "/kiː pərˈfɔːrməns ˈɪndɪkeɪtər/",
  "parts": [
   "key",
   "performance",
   "indicator"
  ],
  "wm": {
   "daily": {
    "en": "a small set of measurable numbers that show whether a person, team, or business is succeeding at what matters most",
    "example": "Store managers track KPIs like sales per square foot and customer return rate.",
    "exampleZh": "店长会追踪每平方英尺销售额、顾客回头率这类关键指标。",
    "zh": "一小撮可量化的数字，用来说明个人、团队或业务在最重要的事情上做得好不好"
   },
   "derivation": [
    {
     "stepLabel": "本义",
     "text": "indicator 是「指示器」——体温计指示你是否发烧，不是发烧本身。key 强调「没有它你就看不清全局」。"
    },
    {
     "stepLabel": "日常引申",
     "text": "零售、销售、HR 早就在用 KPI：少而精，对齐目标。不是「能测的都测」，而是「这几个数字变了，我就知道方向对不对」。"
    },
    {
     "stepLabel": "跨到计算机",
     "text": "工程团队指标爆炸（延迟、错误率、覆盖率……），必须选出 key 的几个，否则人人看不同数字、结论打架。叫 KPI 而不是 metric list，是因为英语刻意强调「钥匙般的少数」——选词是在提醒：别把仪表盘上所有曲线都当 KPI。"
    }
   ],
   "derivationSummary": "钥匙般重要的信号 → 表现好坏的温度计 → 团队对齐「到底看什么算成功」",
   "etymology": "key ← 古英语 cǣg（钥匙、关键）；performance ← 古法语 parfournir（完成、履行）；indicator ← 拉丁语 indicāre（指出）",
   "literal": "字面：标示「表现好不好」的关键信号",
   "oneLiner": "少数几个数字，用来判断「做得好不好」——多了就不是 key 了。",
   "parts": [
    {
     "role": "筛掉噪音——只留最重要的少数几个",
     "senseHint": "关键的",
     "word": "key"
    },
    {
     "role": "衡量的是「做得怎么样」，不是「是什么」",
     "senseHint": "表现、绩效",
     "word": "performance"
    },
    {
     "role": "本身不是结果，而是指向结果的信号",
     "senseHint": "指示信号",
     "word": "indicator"
    }
   ],
   "pitfalls": [
    {
     "right": "KPI 必须 key——通常就几个。If everything is a KPI, nothing is. 如果什么都是关键指标，那就没有关键指标。日常销售 KPI 可能就三五个，不是整张报表。",
     "wrong": "把 KPI 当成「所有指标」"
    },
    {
     "right": "performance 在日常职场里是「表现、业绩」：Her performance review went well. 她绩效评估不错。KPI 可以是客户满意度、交付速度，不一定是系统性能。",
     "wrong": "把 performance 只理解成「性能」"
    },
    {
     "right": "indicator 是指示信号，不是目的。Fever is an indicator of illness. 发烧是生病的指示信号，不是病本身。KPI 下降要追问背后原因，不是为数字而数字。",
     "wrong": "把 indicator 翻译成「指标」后以为它就是目标本身"
    }
   ],
   "tech": {
    "en": "in engineering and product teams, the primary metrics chosen to judge whether systems, releases, or initiatives are meeting their goals, distinct from the full dashboard of everything measurable",
    "example": "Our deployment KPI is lead time from merge to production under two hours.",
    "exampleZh": "我们的部署关键指标是：从合并到上生产不超过两小时。",
    "zh": "在工程和产品团队里，用来判断系统、发布或举措是否达成目标的核心度量，区别于仪表盘上所有可测数据的全集"
   }
  },
  "zh": "关键绩效指标"
 },
