 "service level agreement": {
  "abbr": "SLA",
  "defEn": "a measurable commitment between a service provider and its users—such as availability, latency, or response time—with defined consequences when targets are missed",
  "definition": "服务级别协议。对外的承诺，违约有后果",
  "en": "Service Level Agreement",
  "href": "content/ch07-metrics/7.1-why-measure.html",
  "ipa": "/ˈsɜːrvɪs ˈlevəl əˈɡriːmənt/",
  "parts": [
   "service",
   "level",
   "agreement"
  ],
  "wm": {
   "daily": {
    "en": "a formal contract that spells out what level of service one party must provide and what happens if they fall short",
    "example": "Our internet provider offers a 99.9% uptime SLA in the contract.",
    "exampleZh": "我们的网络服务商在合同里承诺 99.9% 的在线率。",
    "zh": "书面约定一方必须提供何种程度的服务，以及未达标时的后果"
   },
   "derivation": [
    {
     "stepLabel": "本义",
     "text": "agreement 就是双方达成一致的书面约定；level 指「达到哪一档」；service 指你付钱买来的效劳。三个词都是普通商务英语。"
    },
    {
     "stepLabel": "日常引申",
     "text": "电信、快递、保洁合同里早就有 SLA：装宽带承诺多少兆、包裹几天到、打扫频次如何。消费者不一定说这三个词，但「合同里写明的服务标准」这个概念并不专属于软件。"
    },
    {
     "stepLabel": "跨到计算机",
     "text": "线上服务把 level 具体化成 99.95% uptime、200 ms latency。SLA 把模糊的「好好服务」变成可审计的数字，并绑定赔偿或信用——所以英文用 agreement 而不是 promise：它是可诉的合同义务。"
    }
   ],
   "derivationSummary": "合同里写清服务档次 → 云时代把可用性、延迟写进同一份协议",
   "etymology": "service ← 拉丁语 servitium（效劳、服务）；level ← 古法语 livel ← 拉丁语 libella（小天平、水准器），是 lībra（天平、秤）的指小形；agreement ← 古法语 agreer（← a gré「合心意地」← 拉丁语 ad gratum）+ -ment",
   "literal": "字面：关于「服务达到何种水平」的双方约定",
   "oneLiner": "书面约定：服务该做到什么程度，做不到怎么算违约。",
   "parts": [
    {
     "role": "被承诺的对象——提供方要交付什么",
     "senseHint": "服务、效劳",
     "word": "service"
    },
    {
     "role": "量化到什么程度——不是「有没有」，而是「多好」",
     "senseHint": "水平、档次",
     "word": "level"
    },
    {
     "role": "双方签字认可的约束——不是口号",
     "senseHint": "协议、约定",
     "word": "agreement"
    }
   ],
   "pitfalls": [
    {
     "right": "SLA 是「对外承诺的合同条款」，不是仪表盘本身。合同写 99.9% uptime，指标用 SLI 量，两者别混。",
     "wrong": "把 SLA 当成「监控指标」"
    },
    {
     "right": "这里 service 是「你买的服务/效劳」：customer service SLA、cloud service SLA，与 software service 不是一回事。",
     "wrong": "以为 service 在 SLA 里指「微服务」"
    }
   ],
   "tech": {
    "en": "a measurable commitment between a service provider and its users—such as availability, latency, or response time—with defined consequences when targets are missed",
    "example": "If p99 latency exceeds 200 ms for a full month, we breach the SLA.",
    "exampleZh": "若整月 p99 延迟超过 200 毫秒，我们就违反了 SLA。",
    "zh": "服务提供方与用户之间关于可用性、延迟、响应时间等可量化指标的书面承诺，以及未达标时的处理方式"
   }
  },
  "zh": "服务级别协议"
 },
