 "single point of failure": {
  "abbr": "SPOF",
  "defEn": "a component or dependency whose failure will stop the entire system from working, with no redundant fallback",
  "definition": "单点故障。既指技术上的单点，也指「只有一个人会做这件事」的人员单点",
  "en": "Single Point of Failure",
  "href": "content/ch03-key-practices/3.4-sre-resilience.html",
  "ipa": "/ˈsɪŋɡl pɔɪnt əv ˈfeɪljər/",
  "parts": [
   "single",
   "point",
   "failure"
  ],
  "wm": {
   "daily": {
    "en": "one weak link that can cause an entire system or process to collapse if it breaks",
    "example": "Relying on one supplier is a single point of failure for our production line.",
    "exampleZh": "只依赖一家供应商是我们生产线的单点故障。",
    "zh": "一处薄弱环节——它一坏，整个系统或流程就全停"
   },
   "derivation": [
    {
     "stepLabel": "本义",
     "text": "single 就是「唯一的、单独的」。point 可以是地图上的一个点，也可以是流程里的一个环节。failure 是「失效、撑不住」。"
    },
    {
     "stepLabel": "日常引申",
     "text": "这个说法已走出纯 IT：商业、供应链、团队管理里都说 SPOF——「只有一个地方能出问题，而且一出就全完」。It's not just a tech term anymore."
    },
    {
     "stepLabel": "跨到计算机",
     "text": "一台数据库、一个 DNS 服务器、一条网络链路——如果没有备份，它就是 SPOF。架构设计的目标之一，就是消除或隔离这些单点。"
    },
    {
     "stepLabel": "为什么用 point",
     "text": "英语用 point 把复杂系统简化成一张图上的「一个点」——好让你看见：就这里，没有第二条路。redundancy 就是在同一个功能上多加几个 point，避免 single。"
    }
   ],
   "derivationSummary": "single「只有一个」+ point「关键节点」+ failure「它一坏全停」→ 架构里必须消除的致命弱点",
   "etymology": "single ← 拉丁语 singulus（一个一个的）；point、failure 同上",
   "literal": "字面：唯一一处「一坏就全完」的故障点",
   "oneLiner": "只要这一处出问题，整件事就全垮——它是唯一的致命弱点。",
   "parts": [
    {
     "role": "数量限定——只有一个，不是多个",
     "senseHint": "单一的、唯一的",
     "word": "single"
    },
    {
     "role": "位置隐喻——系统里某一个关键节点或环节",
     "senseHint": "点、环节",
     "word": "point"
    },
    {
     "role": "触发事件——这一处坏掉就会引发全线崩溃",
     "senseHint": "故障、失效",
     "word": "failure"
    }
   ],
   "pitfalls": [
    {
     "right": "这里 point 是系统里的「节点、环节」。The weak point in our plan was funding. 我们计划里的薄弱环节是资金。",
     "wrong": "把 point 理解成「观点」或 Git 里的「指针」"
    },
    {
     "right": "failure 在这里是「组件失灵」。A brake failure caused the accident. 刹车失灵导致了事故。",
     "wrong": "以为 failure 只指「项目失败」"
    },
    {
     "right": "关键在「唯一且无备份」。You can have one server that isn't a SPOF if another can take over instantly. 如果另一台能立刻接管，即使只有一台在跑也不算 SPOF。",
     "wrong": "把 single 理解成「单个实例」就够了"
    }
   ],
   "tech": {
    "en": "a component or dependency whose failure will stop the entire system from working, with no redundant fallback",
    "example": "The load balancer was a single point of failure until we deployed a second one.",
    "exampleZh": "在我们部署第二台负载均衡器之前，它就是单点故障。",
    "zh": "系统中没有冗余备份的组件或依赖——它一失效，整个系统就无法继续运行"
   }
  },
  "zh": "单点故障"
 },
