 "site reliability engineering": {
  "abbr": "SRE",
  "badges": [
   "core"
  ],
  "defEn": "a discipline, pioneered at Google, that applies software engineering practices to operations work so large-scale online services stay reliable, scalable, and efficient",
  "definition": "用软件工程的方法解决运维问题、以可靠性为工程目标的实践体系。",
  "en": "Site Reliability Engineering",
  "href": "content/ch03-key-practices/3.4-sre-resilience.html",
  "ipa": "/saɪt rɪˌlaɪəˈbɪlɪti ˌendʒɪˈnɪərɪŋ/",
  "kp": "kp-3-4-1",
  "parts": [
   "site",
   "reliability",
   "engineering"
  ],
  "wm": {
   "derivation": [
    {
     "stepLabel": "组成词义",
     "text": "site 日常是地点：a construction site（工地）、campsite（营地）。reliability 是「靠得住」：a reliable car。engineering 是「用科学方法设计建造」：civil engineering（土木工程）。"
    },
    {
     "stepLabel": "site 在英语里的第二层义",
     "text": "英语里 the site 常指网站/线上服务：The site is down（网站挂了）。SRE 借的是这层——你要守护的是用户访问的那个 running service，不是砖墙工地。"
    },
    {
     "stepLabel": "跨到计算机",
     "text": "传统运维靠人手盯服务器；Google 发现规模一大就不行。SRE 把「让服务可靠」当成工程问题：SLI/SLO、错误预算、自动化、消除重复劳动——用写代码的方式做运维。"
    },
    {
     "stepLabel": "为什么是这三个词",
     "text": "reliability 点出目标（不是 security 或 performance 单独占 C 位，虽然都相关）；engineering 强调方法论（不是 ad-hoc ops）；site 锁定对象是在线服务。三者拼成「用工程手段保障线上服务可靠运行」。"
    }
   ],
   "derivationSummary": "site「线上服务」+ reliability「可依赖地运行」+ engineering「用工程而非救火」→ 把运维变成可设计的系统问题",
   "etymology": "site ← 拉丁语 situs（位置）；reliability ← rely（← 古法语 relier ← 拉丁语 religāre「捆紧、系牢」）+ -ability；engineering ← engineer（← 古法语 engigneor ← 晚期拉丁语 ingeniāre ← 拉丁语 ingenium「天赋、巧思」，晚期拉丁语转指攻城器械）+ -ing；SRE 为 Google 约 2003 年提出的职位名称",
   "literal": "字面：对「站点/服务」的「可靠性」做「工程化」",
   "oneLiner": "用工程方法让线上服务够稳、够快、够可预期——不是等出事再救火。",
   "parts": [
    {
     "role": "被守护的对象——通常指线上服务/网站，不是建筑工地",
     "senseHint": "站点、场所",
     "word": "site"
    },
    {
     "role": "核心目标——按预期稳定运行、少出意外",
     "senseHint": "可靠、可信赖",
     "word": "reliability"
    },
    {
     "role": "手段——用系统化、可度量、可自动化的方法，不是凭手感",
     "senseHint": "工程、设计建造",
     "word": "engineering"
    }
   ],
   "pitfalls": [
    {
     "right": "日常 site 常指物理地点：Meet me at the site after lunch. SRE 里的 site 才特指线上服务。",
     "wrong": "把 site 只翻译成「网站」而忽略它的「地点/现场」本义"
    },
    {
     "right": "日常 reliability 指「可依赖、一致」：She's known for her reliability. 指人办事靠谱，不一定是「零宕机」。",
     "wrong": "以为 reliability 只等于「不出故障」"
    },
    {
     "right": "SRE 的核心是写软件消除运维工作：automate toil, design for failure。engineering 这个词不是装饰。",
     "wrong": "把 SRE 当成「高级运维」而忽略 engineering"
    }
   ],
   "tech": {
    "en": "a discipline, pioneered at Google, that applies software engineering practices to operations work so large-scale online services stay reliable, scalable, and efficient",
    "example": "Our SRE team owns error budgets and on-call rotations for the payment service.",
    "exampleZh": "我们的 SRE 团队负责支付服务的错误预算和值班轮值。",
    "zh": "一种由 Google 开创的学科，把软件工程做法用在运维工作上，让大规模在线服务保持可靠、可扩展且高效"
   }
  },
  "zh": "站点可靠性工程 SRE"
 },
