 "uat": {
  "abbr": "UAT",
  "defEn": "late-stage testing where actual or representative users verify that the system meets business needs and is fit to be accepted before go-live",
  "definition": "用户验收测试。术语表以 Testing (unit, acceptance, integration) 一条收录验收测试，未单列 UAT 这个缩写",
  "en": "UAT",
  "expansion": "User Acceptance Testing",
  "href": "content/ch03-key-practices/3.1-continuous-testing.html",
  "wm": {
   "derivation": [
    {
     "stepLabel": "acceptance 本义",
     "text": "accept a gift（收下礼物）、acceptance into college（被录取）、seek social acceptance（寻求被群体接纳）——核心都是「认可并接收」。"
    },
    {
     "stepLabel": "日常 testing",
     "text": "testing 不一定是实验室：market testing（市场试销）、testing a theory（验证一个想法）都强调「先试一下再下结论」。"
    },
    {
     "stepLabel": "跨到软件",
     "text": "功能在开发者眼里 done 还不够；要问 end user 能不能完成真实工作、愿不愿意签收。UAT 回答的是 fit for use and fit for acceptance。"
    },
    {
     "stepLabel": "为什么强调 user",
     "text": "QA 查的是产品是否符合规格；UAT 查的是用户是否愿意接受这个产品去干活。英语用 user acceptance，因为签收权往往在用户/业务方，不在测试团队。"
    }
   ],
   "derivationSummary": "accept「取来、收下」→ acceptance「认可并接收」→ 用户试过后愿意签收，才算通过",
   "etymology": "user ← use + -er；acceptance ← 拉丁语 acceptāre（take to oneself）← ad + capere（take）；testing ← test",
   "literal": "字面：由用户来做的「是否接受」之检验",
   "oneLiner": "让真实用户（或代表用户的人）试一遍，看产品是否够好、能否被正式接受。",
   "parts": [
    {
     "role": "视角来源——不是开发自测，而是从使用者出发",
     "senseHint": "用户、使用者",
     "word": "user"
    },
    {
     "role": "判定标准——重点在「能不能被接受/签收」",
     "senseHint": "接受、认可",
     "word": "acceptance"
    },
    {
     "role": "手段——通过真实试用来做判断",
     "senseHint": "测试、试用",
     "word": "testing"
    }
   ],
   "pitfalls": [
    {
     "right": "acceptance speech 是获奖感言，letter of acceptance 是录取通知。UAT 问的是 users can accept this product，不只是 checklist 打勾。",
     "wrong": "把 acceptance 只翻译成「验收」而忽略「愿意接受」的人际含义"
    },
    {
     "right": "QA 偏过程与规格一致性；UAT 偏业务方最终签收。可以说 QA passed, but UAT failed because reports were too slow for accountants。",
     "wrong": "把 UAT 和 QA 当成同一件事"
    }
   ],
   "tech": {
    "en": "late-stage testing where actual or representative users verify that the system meets business needs and is fit to be accepted before go-live",
    "example": "UAT starts after QA signs off, with finance users running real month-end workflows.",
    "exampleZh": "QA 签字后启动 UAT，由财务用户跑真实的月末流程。",
    "zh": "在上线前的后期测试阶段，由真实用户或用户代表验证系统是否满足业务需求、是否达到可正式接收的标准"
   }
  },
  "zh": "用户验收测试"
 },
