 "velocity": {
  "defEn": "the amount of backlog work a team consistently completes per iteration, measured in story points or similar units, used to forecast future capacity",
  "definition": "一个 Sprint 内团队完成的故事点数，用于本团队的容量预测 —— 不能跨团队比较，也不是绩效。",
  "en": "Velocity",
  "href": "content/ch04-frameworks/4.2-agile-scrum.html",
  "ipa": "/vəˈlɒsəti/",
  "wm": {
   "daily": {
    "en": "how fast something is moving in a given direction; figuratively, how fast something is gathering momentum",
    "example": "The rumour gained velocity as soon as the video was shared.",
    "exampleZh": "视频一被转发，那个传言就迅速扩散开来。",
    "zh": "某物朝某个方向移动的快慢；引申指某件事推进、发酵的势头有多猛"
   },
   "derivation": [
    {
     "stepLabel": "本义",
     "text": "velocity 是物理学术语：不只有多快（speed），还有方向。一辆车朝北 60 mph 和朝南 60 mph，speed 相同，velocity 不同。"
    },
    {
     "stepLabel": "日常引申",
     "text": "非物理语境里 velocity 比喻「事物推进有多猛」：The story gained velocity（事态加速发酵）、high-velocity sales（高速成交）。都强调「单位时间里往前推进了多少」。"
    },
    {
     "stepLabel": "跨到计算机",
     "text": "敏捷需要预测「下个迭代能做完多少」。英文借 velocity 而不是 speed，是因为团队关心的是「朝交付方向稳定推进的速率」——一个可观测、可平均、可外推的数字，就像物理里可测量的矢量大小。"
    }
   ],
   "derivationSummary": "物理上的定向速度 → 单位时间里完成了多少 → 团队每个迭代稳定产出多少工作",
   "etymology": "velocity ← 拉丁语 vēlōcitās ← vēlōx（快速的）",
   "literal": "字面：「快速」这一性质本身",
   "morphemes": [
    {
     "from": "拉丁语 velox / veloc-（swift, fast）",
     "meaning": "快速的",
     "piece": "veloc"
    },
    {
     "from": "拉丁语 -itas",
     "meaning": "性质、状态（名词后缀）",
     "piece": "ity"
    }
   ],
   "oneLiner": "物体沿某个方向移动有多快；敏捷里指团队每个迭代实际完成了多少工作量。",
   "pitfalls": [
    {
     "right": "物理课里 velocity 带方向，speed 不带。日常说 gain velocity 强调「势头在加快」。敏捷里的 velocity 是「完成量」，不是「人有多忙」。",
     "wrong": "把 velocity 当成「速度」然后和 speed 完全混用"
    },
    {
     "right": "velocity 是团队自己的度量尺，不能跨团队比较。日常类比：两辆车的 velocity 只有在同一条路、同一单位下才有可比性。",
     "wrong": "以为 velocity 越高团队越优秀"
    }
   ],
   "tech": {
    "en": "the amount of backlog work a team consistently completes per iteration, measured in story points or similar units, used to forecast future capacity",
    "example": "Our average velocity is 32 points per sprint.",
    "exampleZh": "我们每个冲刺的平均速率是三十二个故事点。",
    "zh": "团队在每个迭代中稳定完成的工作量，通常用故事点等单位衡量，用来预测未来能交付多少"
   }
  },
  "zh": "Velocity 速率"
 },
