 "wip": {
  "abbr": "WIP",
  "defEn": "in Kanban and lean software delivery, the inventory of items actively being worked on at each stage; WIP limits cap how many items may be in flight to reduce context-switching and bottlenecks",
  "definition": "在制品。看板的核心动作是限制在制品；术语表收录的是 Kanban 与 Flow，未单列 WIP",
  "en": "WIP",
  "expansion": "Work in progress",
  "href": "content/ch03-key-practices/3.7-kanban.html",
  "wm": {
   "daily": {
    "en": "something that has been started but is not finished yet",
    "example": "Sorry for the mess—the kitchen renovation is still a work in progress.",
    "exampleZh": "抱歉这么乱——厨房装修还在进行中。",
    "zh": "已经开始但尚未完成的事情"
   },
   "derivation": [
    {
     "stepLabel": "本义",
     "text": "work 是劳作、任务；progress 是「向前推进」——in progress 即「正在进行、尚未到头」。"
    },
    {
     "stepLabel": "日常引申",
     "text": "工地门口常见 Work in progress（施工中）；形容人也可以说 My Spanish is a work in progress（我的西语还在学）。核心都是：开了头，还没完。"
    },
    {
     "stepLabel": "跨到计算机",
     "text": "工厂用「在制品库存」描述流水线上半成品的堆积。软件开发同理：同时开着五个 PR、三个需求、两个 incident，这些都是 WIP。Kanban 用 WIP limit 限制「在途」数量，因为 unfinished work 是成本，不是资产。"
    },
    {
     "stepLabel": "为什么借用这个日常短语",
     "text": "英语没有用半成品这种制造隐喻造新词，而是直接拿 work in progress——因为它准确描述「已投入但未交付」的状态。limit 的是 progress 中的 work，不是 completed work。"
    }
   ],
   "derivationSummary": "work「活」+ in progress「在推进、没做完」→ 已开始但未交付的「在途库存」",
   "etymology": "work ← 古英语 weorc（行为、劳作）；progress ← 拉丁语 prōgressus（向前走）← prō- + gradī（迈步）",
   "literal": "字面：进行中的工作",
   "oneLiner": "已经开工、尚未做完的那部分活。",
   "parts": [
    {
     "role": "核心——正在进行的事务、劳动",
     "senseHint": "工作",
     "word": "work"
    },
    {
     "role": "状态——在进行中、尚未终结",
     "senseHint": "进行中",
     "word": "progress"
    }
   ],
   "pitfalls": [
    {
     "right": "in progress 是固定短语，表状态「进行中」：The meeting is in progress（会议正在进行）。不是「有进步」，是「还没结束」。a work in progress = 进行中的工程。",
     "wrong": "把 progress 理解成「进步、进展」"
    },
    {
     "right": "日常 WIP 包含一切未完工项：a novel in progress（写了一半的小说）。技术里 WIP 覆盖需求、评审、测试、部署各阶段的在途项，不只是 coding。",
     "wrong": "以为 WIP 只指「当前正在写的代码」"
    }
   ],
   "tech": {
    "en": "in Kanban and lean software delivery, the inventory of items actively being worked on at each stage; WIP limits cap how many items may be in flight to reduce context-switching and bottlenecks",
    "example": "We've hit the WIP limit on code review—finish reviewing before starting new stories.",
    "exampleZh": "代码评审已到在制品上限——先审完再开新需求。",
    "zh": "看板与精益交付里，各阶段正在处理、尚未完成的工作项存量；WIP 上限限制同时进行中的数量，以减少切换成本和瓶颈"
   }
  },
  "zh": "在制品"
 },
