  "pitfall": "conflict 不只是 Git 专有词。family conflict = 家庭矛盾，conflict of interest = 利益冲突，schedules conflict = 时间冲突——日常极多，别只在合并代码时才想起这个词。",
  "pos": "n. / v.",
  "techShift": "Git merge conflict 就是两份改动在同一处「撞车」——和两个人抢同一会议室、两条规则互相打架是同一意象；解决 conflict 在生活和在版本库里都是「把撞车理顺」。",
  "zh": "①冲突、争执、对立 ②（日程、利益、说法的）矛盾、不一致 ③【动词】与…冲突、抵触"
