 "containers": {
  "cognates": [
   "contain",
   "content",
   "continent",
   "continence",
   "retain"
  ],
  "en": "something that holds other things; a large metal box for shipping goods",
  "etymology": "拉丁语 continēre（con- 一起 + tenēre 握住 = 装住、容纳）→ 古法语 contenir → 英语 contain；container = contain + 施事后缀 -er（15 世纪中英语内部构词）",
  "example": "Store the leftovers in an airtight container.",
  "exampleZh": "把剩菜放进密封容器里。",
  "lemma": "container",
  "literal": "本义：把东西「装在里面、握住不外泄」的东西",
  "pitfall": "container 首先是「装东西的器皿」。plastic container = 塑料盒，shipping container = 海运集装箱，a container of yogurt = 一盒酸奶——都是实物；别一上来就只想 Docker。",
  "pos": "n.",
  "techShift": "Docker container 借的是货运集装箱意象：标准化外壳里打包好一整套运行环境，可搬运、可叠放；DI 里的 dependency injection container 则是「把依赖装在一起的箱子」。",
  "zh": "①容器（装东西的盒子、瓶子、罐子）②（货运）集装箱"
 },
 "continuing": {
  "ipa": "/kənˈtinjuiŋ/",
  "zh": "a. 继续的、持续的、连续的"
 },
 "continuous": {
  "cognates": [
   "continue",
   "continuity",
   "contain",
   "content"
  ],
  "en": "without stopping or breaks; going on steadily",
  "etymology": "拉丁语 continere（握在一起、连在一起）→ continuus → 英语 continuous",
  "example": "The continuous rain kept us indoors all weekend.",
  "exampleZh": "雨下个不停，我们整个周末都没出门。",
  "ipa": "/kənˈtɪnjuəs/",
  "literal": "本义：各环节「首尾相接、不断开」",
  "pitfall": "别把 continuous 理解成「一直在线」或「实时」。日常里 continuous improvement = 持续改进，continuous stream = 不间断的水流。CI/CD 说的是「改完就自动接上下一步」，不是说系统 24 小时不能有毫秒级中断。",
  "pos": "adj.",
  "techShift": "continuous integration / continuous delivery 强调流水线「一次次接上、少靠人工停顿」：代码改完就自动构建、测试、往可发布状态推进——取的是「不间断的过程」，不是「连续函数」那种数学专门义。",
  "zh": "①连续不断的、没有中断的 ②持续的（continuous rain / noise）"
 },
 "control": {
  "cognates": [
   "counter",
   "contrast"
  ],
  "en": "power to direct or restrain; a standard for comparison in experiments; (v.) to direct, govern, or hold back",
  "etymology": "中世纪拉丁语 contrarotulus（对照账册、核对用的副本）→ 古法语 contrôle（核对、检查）→ 英语 control",
  "example": "She struggled to control her anger during the meeting.",
  "exampleZh": "开会时她努力压住自己的怒火。",
  "ipa": "/kənˈtroʊl/",
  "literal": "本义：拿「对照账册」去核对、把关",
  "pitfall": "别把 control 只读成「控件」。out of control = 失控，birth control = 避孕，control group = 对照组，under control = 局面已控制住——日常里多是「管住/支配」，不是 UI 上的按钮。",
  "pos": "n. / v.",
  "techShift": "工程里的 control 先是「把系统变量管住、按目标调节」——像实验里的对照组一样，拿期望行为去比对实际行为；控制面（control plane）、访问控制（access control）都是「谁有权管、按什么规则管」。",
  "zh": "①【名词】控制、支配、管理权 ②【名词】对照组、对照标准（实验里与实验组比较的那一组） ③【动词】控制、支配、抑制（情绪、局面等）"
 },
