  "en": "happening every day; each day; (n.) a newspaper published every day",
  "etymology": "古英语 dæglic（每日的）← dæg（日、天）+ -lic（-ly）→ 中古英语 dayly → daily",
  "example": "Exercise has become part of my daily routine.",
  "exampleZh": "锻炼已经成了我日常习惯的一部分。",
