  "literal": "本义：「属于日子的、按天来的」",
  "pitfall": "别把 daily 只当成 stand-up 的缩写。daily life = 日常生活，daily newspaper = 日报，twice daily = 每日两次——先想到「每天的/日常」，再想到敏捷里的 daily。",
  "pos": "adj. / adv. / n.",
  "techShift": "daily build、daily stand-up、daily active users 用的就是「按天发生」：每天一版构建、每天碰一次的短会、每天活跃的人数——没有额外隐喻，就是把 ordinary 的时间粒度用在工程节奏和指标上。",
