  "ipa": "/dɪˈklærətɪv/",
  "literal": "本义：具有「把事讲清楚、正式表明」的性质",
  "pitfall": "别把 declarative 只当成 Kubernetes 术语。语法课里 declarative sentence = 陈述句；He spoke in short, declarative sentences = 他用简短的陈述句平铺直叙——意思是「说明事实」，不是写 YAML。",
