  "techShift": "server load、workload 沿用「担子有多重」：请求越多，机器越「背不动」；load balancer 像把货物分装到多辆车上，避免一辆车压垮；load testing 则是故意把担子加满看会不会垮。",
  "zh": "①负载、重物 ②（动词）装载、装满 ③工作量、负担 ④（电器）负荷"
