 "loop": {
  "en": "a doubled-over ring of rope or cord; a route that comes back to where it started; the circle of people who are kept informed",
  "etymology": "名词 14 世纪晚期首见，「布、绳、皮条折成的一个环」，来源存疑：牛津词典倾向凯尔特语来源（比较盖尔语 lub「弯」、爱尔兰语 lubiam），也可能受古诺尔斯语 hlaup「跳跃、奔跑」影响。指纹的「环」义 1880 年，胶片与磁带的「循环片段」义 1931 年，程序里的「循环」义 1947 年。",
  "example": "Keep me in the loop about the move, will you?",
  "exampleZh": "搬家的事有进展记得跟我说一声，好吗？",
  "ipa": "/luːp/",
  "literal": "本义：绳子折回来打成的一个环",
  "pitfall": "别让「循环」挤掉它的日常义。三个高频说法：Keep me in the loop.（有进展记得告诉我）/ I'm out of the loop on this.（这事我不知情）/ a belt loop（裤子上的皮带袢）。另外 loop the loop 是飞机翻筋斗。",
  "pos": "n. / v.",
  "techShift": "程序里的 loop（循环）取的是「绕回起点」这一支——走到头又回到开头。办公语里的 in the loop、loop someone in 取的是另一支：消息在一个闭合的环里流转，在环里的人自动收得到。两支都来自「环」，但一个说路径，一个说圈子。",
  "zh": "①绳、布、线折回来打成的圈或环：a loop of rope ②环形的路线：绕城一圈的公交环线 ③知情的圈子：in the loop（在圈内、知情）／out of the loop（被蒙在鼓里）④【动词】打圈、绕成环；loop someone in 就是把某人拉进来"
 },
